/** @brief Issue the instruction of id through its builtin: run(fields...) with the fields as operands, word<W>()
 *         with the fields of the compile-time word W. */
template <std::uint32_t Id>
struct Emit;

#if __has_builtin(__builtin_rvtt_bh_mop)
template <>
struct Emit<0x2u> // MOP
{
    static inline __attribute__((always_inline)) void run(const std::uint32_t f0, const std::uint32_t f1, const std::uint32_t f2)
    {
        ::__instrn_buffer[0] = __builtin_rvtt_bh_mop(f0, f1, f2);
    }

    template <std::uint32_t W>
    static inline __attribute__((always_inline)) void word()
    {
        run((W >> 23) & 0x1u, (W >> 16) & 0x7fu, (W >> 0) & 0xffffu);
    }
};
#endif

